import{_ as o,o as d,c as t,a2 as r}from"./chunks/framework.CNDaxUod.js";const E=JSON.parse('{"title":"云同步发布检查清单","description":"","frontmatter":{},"headers":[],"relativePath":"zh/operations/cloud-sync-rollout.md","filePath":"zh/operations/cloud-sync-rollout.md","lastUpdated":1788607300000}'),c={name:"zh/operations/cloud-sync-rollout.md"};function l(a,e,i,s,u,n){return d(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="云同步发布检查清单" tabindex="-1">云同步发布检查清单 <a class="header-anchor" href="#云同步发布检查清单" aria-label="Permalink to &quot;云同步发布检查清单&quot;">​</a></h1><p>云同步横跨三个仓库，并由两个独立开关控制。在后端依赖和 SSO Client Registry 全部就绪前，必须保持关闭状态。</p><h2 id="仅开启账号登录" tabindex="-1">仅开启账号登录 <a class="header-anchor" href="#仅开启账号登录" aria-label="Permalink to &quot;仅开启账号登录&quot;">​</a></h2><p>账号会话与云简历分开发布：</p><ul><li>Pages 生产构建设置 <code>VITE_YLF_LOGIN_ENABLED=true</code>、<code>VITE_YLF_CLOUD_ENABLED=false</code>。</li><li>Drive 设置 <code>NUXT_WEB_RESUME_LOGIN_ENABLED=true</code>，云简历开关 <code>NUXT_WEB_RESUME_ENABLED</code> 保持关闭。</li><li>主域实际由 Cloudflare Worker <code>web-resume</code> 转发静态资源到 <code>resume.elpsy.cn</code>。使用仓库 <code>workers/wrangler.toml</code> 发布 Worker；它直接处理 <code>/api/*</code>，保留 <code>resume.yunle.fun</code> 的 Origin，并使用 <code>YLF_LOGIN_API_ENABLED=true</code>、<code>YLF_CLOUD_API_ENABLED=false</code>。</li><li>Cloudflare 为 <code>https://drive.yunle.fun/api/v1/web-resume/*</code> 配置 SSL <code>strict</code> Page Rule；否则 zone 的 Flexible SSL 会使 Worker 回源 HTTP，与 Drive 的 HTTPS 跳转形成循环。不要通过跟随重定向或关闭证书验证解决。</li><li>镜像 Pages 的 API 开关保持关闭；域名白名单让相同构建在镜像站仍不显示登录。</li><li>匿名 <code>/api/session</code> 应返回 401，<code>/api/documents</code> 应返回 404。登录不会自动上传简历，也不会覆盖本地联系资料。</li></ul><h3 id="apps-yunle-fun-模拟器验收" tabindex="-1">apps.yunle.fun 模拟器验收 <a class="header-anchor" href="#apps-yunle-fun-模拟器验收" aria-label="Permalink to &quot;apps.yunle.fun 模拟器验收&quot;">​</a></h3><ol><li>启动本地云乐坊 iOS 模拟器应用，登录测试账号。</li><li>在应用内打开 <code>https://resume.yunle.fun/user</code>，点击“使用云乐坊账号登录”。必须在宿主内嵌浏览器打开，而不是系统 Safari。</li><li>应出现带 Web Resume 名称及来源的宿主授权确认；确认后页面显示账号，刷新后仍保持会话。</li><li>取消应回到可重试状态；未登录宿主应先引导登录，再返回授权。账号资料不得覆盖本地姓名、电话和邮箱。</li><li>本地开发仅使用已注册的 <code>https://resume.yunle.localhost:3455</code>；开发后端 Origin 也需精确匹配，不要为了模拟器添加通配域名或绕过证书校验。</li></ol><h2 id="范围与生产配置" tabindex="-1">范围与生产配置 <a class="header-anchor" href="#范围与生产配置" aria-label="Permalink to &quot;范围与生产配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>生产值</th></tr></thead><tbody><tr><td>Web Resume Origin</td><td><code>https://resume.yunle.fun</code></td></tr><tr><td>SSO client / app</td><td><code>web-resume-web</code> / <code>web-resume</code></td></tr><tr><td>Redirect</td><td><code>https://resume.yunle.fun/user</code></td></tr><tr><td>Scope</td><td><code>identity:bootstrap</code></td></tr><tr><td>Drive BFF 前缀</td><td><code>https://drive.yunle.fun/api/v1/web-resume</code></td></tr><tr><td>元数据集合</td><td><code>web_resume_documents</code>（<code>ADMINONLY</code>）</td></tr><tr><td>单份简历上限</td><td>2 MiB</td></tr><tr><td>回收站保留</td><td>30 天</td></tr></tbody></table><p>唯一注册的开发 Origin 是 <code>https://resume.yunle.localhost:3455</code>，回调路径为 <code>/user</code>。预览域名和镜像站必须保持云同步关闭。</p><h2 id="部署前检查" tabindex="-1">部署前检查 <a class="header-anchor" href="#部署前检查" aria-label="Permalink to &quot;部署前检查&quot;">​</a></h2><ol><li>在 <code>www.yunle.fun</code> 中创建 <code>web_resume_documents</code>，设置 <code>ADMINONLY</code> 权限，并创建 <code>cloudfunctions/user-storage-api/web-resume-resources.js</code> 声明的全部索引。</li><li>生成两个彼此独立、至少 32 bytes 的随机服务令牌。<code>WEB_RESUME_STORAGE_INTERNAL_TOKEN</code> 同时配置到 <code>user-storage-api</code> 与 Drive BFF；<code>WEB_RESUME_SWEEPER_INTERNAL_TOKEN</code> 同时配置到两个存储云函数。令牌不得出现在公开变量或 <code>VITE_</code> 变量中。</li><li>私有 COS Bucket 继续保持 private。CORS 只允许精确生产 Origin、<code>PUT</code> 和 <code>Content-Type</code>，不得使用通配 Origin 或携带凭据的跨域规则。</li><li>部署更新后的 <code>user-storage-api</code> 和私有 <code>web-resume-storage-sweeper</code>，验证一次存储预留、完成、删除闭环，以及 sweeper 返回的有界计数。</li><li>为 Drive 配好全部 <code>NUXT_WEB_RESUME_*</code>，但先保持 <code>NUXT_WEB_RESUME_ENABLED=false</code>。确认会话存储、限流集合、CloudBase 凭据和 CSRF secret 健康。</li><li>审阅 <code>www.yunle.fun/specs/sso-client-registry-platform/drafts/</code> 中已生成但未签名的生产与开发草案，走现有审批和签名发布流程；不得手改或发布未签名草案。</li></ol><h2 id="开启顺序" tabindex="-1">开启顺序 <a class="header-anchor" href="#开启顺序" aria-label="Permalink to &quot;开启顺序&quot;">​</a></h2><ol><li>在 Drive 开启 <code>NUXT_WEB_RESUME_ENABLED=true</code>。前端尚未开启时，先确认匿名请求返回 <code>401</code>、非允许 Origin 返回 <code>403</code>，并用获准测试账号验证 Drive 只读入口。</li><li>使用真实测试账号完成 SSO、首次保存、自动保存、下载、冲突副本、回收站、恢复、退出和第二设备会话。核对原始 YAML 校验和及共享配额变化。</li><li>使用 <code>apps/web/.env.example</code> 中的生产配置，并设置 <code>VITE_YLF_CLOUD_ENABLED=true</code> 构建 Web Resume；同一发布中开启 Cloudflare Pages 运行时开关 <code>YLF_CLOUD_API_ENABLED=true</code>。</li><li>在桌面端和移动端完成浏览器冒烟。桌面端应同时显示右上角账号入口和“我的”，移动端只显示底部“我的”。</li><li>观察会话交换、存储 reserve/finalize 失败、冲突副本率、配额变化和回收站清理错误，再逐步扩大流量。</li></ol><h2 id="回滚" tabindex="-1">回滚 <a class="header-anchor" href="#回滚" aria-label="Permalink to &quot;回滚&quot;">​</a></h2><p>先关闭 <code>YLF_CLOUD_API_ENABLED</code>，切断同源代理，再关闭 <code>NUXT_WEB_RESUME_ENABLED</code>。随后可以用 <code>VITE_YLF_CLOUD_ENABLED=false</code> 重新构建前端以隐藏界面。保留 Registry 条目、元数据集合、私有对象和清理任务，确保已有用户数据仍可恢复；回滚不得删除云端简历。</p>',16)])])}const p=o(c,[["render",l]]);export{E as __pageData,p as default};
